using AcxiomCRM.Web.Data;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using AcxiomCRM.Web.Models;
namespace AcxiomCRM.Web.Controllers;[Authorize(Roles="Admin,Manager")]public class ReportsController:Controller{readonly ApplicationDbContext db;readonly UserManager<ApplicationUser> um;public ReportsController(ApplicationDbContext d,UserManager<ApplicationUser> u){db=d;um=u;}public async Task<IActionResult>Index(){var opp=await db.Opportunities.Include(o=>o.Owner).Include(o=>o.Customer).ToListAsync();var leads=await db.Leads.ToListAsync();ViewBag.Conversion=leads.Count==0?0:Math.Round(leads.Count(x=>x.Status==LeadStatus.Converted)*100m/leads.Count,1);return View(opp);}public async Task<IActionResult>ExportOpportunities(){var rows=await db.Opportunities.Include(o=>o.Customer).Include(o=>o.Owner).ToListAsync();var csv="Opportunity,Customer,Stage,Amount,Probability,ExpectedClose,Owner
"+string.Join("
",rows.Select(o=>$""{o.OpportunityName.Replace(""","""")}","{o.Customer?.CustomerName}",{o.Stage},{o.Amount},{o.Probability},{o.ExpectedCloseDate:yyyy-MM-dd},"{o.Owner?.FullName}""));return File(System.Text.Encoding.UTF8.GetBytes(csv),"text/csv","opportunities.csv");}}
